mapper.select:
SELECT s.id, s.doctor_id AS doctorId, d.name AS doctorName, d.department_id AS departmentId, dept.name AS departmentName, s.schedule_date AS scheduleDate, s.time_slot AS timeSlot, s.start_time AS startTime, s.end_time AS endTime, s.max_appointments AS maxAppointments, s.current_appointments AS currentAppointments, s.status FROM schedule s LEFT JOIN doctor d ON d.id = s.doctor_id LEFT JOIN department dept ON dept.id = d.department_id
AND s.schedule_date = #{date}
AND d.department_id = #{deptId}
ORDER BY s.schedule_date DESC, s.start_time
